/* @autogenerated */
package net.civeira.phylax.features.oauth.client.application;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.client.domain.gateway.JwtReplayGateway;

class ClientAssertionVerifierUnitTest {

  private static final String ISSUER = "https://auth.example.com/oauth/openid/acme";
  private static final ClientDetails CLIENT = ClientDetails.builder().clientId("svc")
      .allowedScopes(List.of()).allowedGrants(List.of("client_credentials"))
      .tokenEndpointAuthSigningAlg("ES256").build();

  private Map<String, Object> claims;
  private final Set<String> used = new HashSet<>();
  private final List<String> purposes = new ArrayList<>();
  private final List<String> algorithms = new ArrayList<>();
  private ClientAssertionVerifier verifier;

  @BeforeEach
  void setUp() {
    claims = new HashMap<>();
    claims.put("iss", "svc");
    claims.put("sub", "svc");
    claims.put("aud", ISSUER + "/token");
    claims.put("exp", Instant.now().plusSeconds(120).getEpochSecond());
    claims.put("jti", "a-1");
    verifier = new ClientAssertionVerifier((client, jwt, alg) -> {
      algorithms.add(alg);
      return Optional.of(claims);
    }, (tenant, clientId, purpose, jti, exp) -> {
      purposes.add(purpose);
      return used.add(jti);
    });
  }

  private boolean verify() {
    return verifier.verify("acme", ISSUER, CLIENT, "jwt");
  }

  @Test
  @DisplayName("A valid assertion is accepted once, with the registered algorithm")
  void valid_once() {
    Assertions.assertTrue(verify());
    Assertions.assertFalse(verify(), "Replay");
    Assertions.assertEquals("ES256", algorithms.get(0));
    Assertions.assertEquals(JwtReplayGateway.CLIENT_SIGNED, purposes.get(0),
        "Shared with request objects");
  }

  @Test
  @DisplayName("iss and sub must both be the client")
  void issuer_and_subject() {
    claims.put("sub", "other");
    Assertions.assertFalse(verify());
    claims.put("sub", "svc");
    claims.put("iss", "other");
    Assertions.assertFalse(verify());
  }

  @Test
  @DisplayName("The audience is the issuer or one of its endpoints")
  void audience() {
    claims.put("aud", List.of("https://other", ISSUER));
    Assertions.assertTrue(verify());
    claims.put("jti", "a-2");
    claims.put("aud", ISSUER + "/token?x=1");
    Assertions.assertFalse(verify());
    claims.put("aud", ISSUER + "other/token");
    Assertions.assertFalse(verify());
  }

  @Test
  @DisplayName("exp and jti are required, and the lifetime is at most an hour")
  void time_and_identifier() {
    claims.remove("exp");
    Assertions.assertFalse(verify());
    claims.put("exp", Instant.now().plusSeconds(7200).getEpochSecond());
    Assertions.assertFalse(verify());
    claims.put("exp", Instant.now().plusSeconds(60).getEpochSecond());
    claims.remove("jti");
    Assertions.assertFalse(verify());
  }

  @Test
  @DisplayName("A request object is not an assertion")
  void request_object() {
    claims.put("response_type", "code");
    Assertions.assertFalse(verify());
  }
}
